import itertools

def calculate_C(A, n):
    """
    Calculates C(A) = number of triples (x, y, z) in A^3 such that x+y+z is divisible by n.
    A is a subset of {1, ..., n}.
    """
    if not A:
        return 0

    # Calculate residue counts a_r for r = 0, 1, ..., n-1
    a = [0] * n
    for x in A:
        r = x % n
        a[r] += 1

    count = 0
    # Iterate over all combinations of residues (i, j, k)
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if (i + j + k) % n == 0:
                    count += a[i] * a[j] * a[k]
    return count

# Search for small n (1 to 15) and check for small target counts (T=1, 2, 3)
max_n = 15
target_counts = {1, 2, 3}
results = {}

print("Starting search...")

for n in range(1, max_n + 1):
    print(f"\n--- Testing n = {n} ---")

    # Iterate over all 2^n possible colorings R (Red set)
    # We represent the coloring by a bitmask from 0 to 2^n - 1.
    # If the j-th bit is 1, j+1 is in R (Red).

    found_small_T = False

    for mask in range(1 << n):
        R = set()
        for j in range(n):
            if (mask >> j) & 1:
                R.add(j + 1)

        B = set(range(1, n + 1)) - R

        C_R = calculate_C(R, n)
        C_B = calculate_C(B, n)
        T = C_R + C_B

        if T in target_counts:
            results[n] = {
                'T': T, 
                'R_size': len(R), 
                'R_set': R, 
                'B_set': B,
                'C_R': C_R,
                'C_B': C_B
            }
            found_small_T = True
            # Stop searching for this n once a small target is found
            break 

    if found_small_T:
        print(f"Found a solution for T in {target_counts} for n={n}")


print("\n--- Search Summary ---")
for n, data in results.items():
    print(f"n={n}, T={data['T']}. |R|={data['R_size']}. R={sorted(list(data['R_set']))}")

if not results:
    print("No solution found for T=1, 2, or 3 up to n=15.")
